  ('a0a0f804-c601-4747-a748-8e804ab9190c', '5019346f-6990-474d-9d53-74abf93267f8', $$krantenbericht: Denemarken voert accijns op verzadigd vet in (met cartoon)$$,
   $$economie-havo-2016-i-slaat-accijns-een-deuk-in-een-pakje-boter-context1.png$$,
   $$uit een krant, oktober 2011 Denemarken is het eerste land dat accijns op verzadigd vet invoert. Door deze belasting is verzadigd vet nu een stuk duurder. En dat geldt voor alle verzadigde vetten, of ze nu in koekjes of in melk zitten. De Deense overheid hoopt met de belasting te bewerkstelligen dat er minder verzadigde vetten worden geconsumeerd. Zo moeten overgewicht en hart- en vaatziekten bij de Deense bevolking worden tegengegaan.$$, 'inline'),
  ('32793843-a784-4a4c-83b7-999521bb8163', '5019346f-6990-474d-9d53-74abf93267f8', $$doel Deense overheid: boterconsumptie met één derde beperken; prijs vóór accijns € 4$$,
   $$economie-havo-2016-i-slaat-accijns-een-deuk-in-een-pakje-boter-context2.png$$,
   $$Boter bevat verzadigde vetten. De Deense overheid heeft met de invoering van accijns op vet als doelstelling de consumptie van boter met minimaal één derde te beperken. Stel dat in Denemarken de prijs van een kilo boter vóór invoering van de accijns € 4 bedraagt.$$, 'inline'),
  ('8243fca0-1a95-42a2-82bf-bfb7522e321b', '5019346f-6990-474d-9d53-74abf93267f8', $$gedragseconoom: consumenten laten zich ook leiden door emoties en gewoontes$$,
   $$economie-havo-2016-i-slaat-accijns-een-deuk-in-een-pakje-boter-context3.png$$,
   $$Een gedragseconoom is tegen de accijnsheffing en doet de volgende uitspraak: “Consumenten zijn geen robots die alleen reageren op de prijs; ze laten zich ook leiden door emoties en gewoontes.”$$, 'inline'),
  ('65c603e2-7f48-43cb-85f5-b032756dfa84', '5019346f-6990-474d-9d53-74abf93267f8', $$bron 1: botermarkt in Denemarken (vraag- en aanbodlijnen met en zonder accijns)$$,
   $$economie-havo-2016-i-slaat-accijns-een-deuk-in-een-pakje-boter-context4.png$$,
   $$bron 1 botermarkt in Denemarken
grafiek: prijs (P) (€ per kilo, 0-8) tegen hoeveelheid boter (Q) (miljoenen kilo''s, 0-8)
aanbod met accijns: Qa = 2P − 8
aanbod zonder accijns: Qa = 2P − 4
vraag: Qv = −P + 8
evenwicht zonder accijns bij P = 4 en Q = 4 (stippellijnen)$$, 'inline'),
  ('42c948f7-a564-4ea1-8621-6b4afc65bfcd', '5019346f-6990-474d-9d53-74abf93267f8', $$bron 2: antwoordmogelijkheden bij vraag 20 (grafiek 1 t/m 4)$$,
   $$economie-havo-2016-i-slaat-accijns-een-deuk-in-een-pakje-boter-context5.png$$,
   $$bron 2 antwoordmogelijkheden bij vraag 20
vier grafieken (grafiek 1 t/m 4), elk met prijs (P) (€ per kilo) tegen hoeveelheid boter (Q) (miljoenen kilo''s), de lijnen ''aanbod met accijns'', ''aanbod zonder accijns'' en ''vraag'', en telkens een ander grijs vlak$$, 'inline'),
  ('407050ae-831b-485d-8c39-7533dd8a9a17', '1545093b-8501-42d0-bebe-0ec82fee64cd', $$inleiding: conjunctuur India omgeslagen; inflatie, tekort lopende rekening; automatische stabilisatoren$$,
   $$economie-havo-2016-i-in-india-is-het-niet-alles-goud-wat-er-blinkt-context1.png$$,
   $$De afgelopen tien jaar heeft de Indiase economie zich snel ontwikkeld. Maar door onder andere afnemend consumentenvertrouwen is de conjunctuur omgeslagen en behoort India nu tot de economisch meest kwetsbare landen. Zo heeft de economie last van oplopende inflatie, een tekort op de lopende rekening van de betalingsbalans en kapitaalexport naar de Verenigde Staten (VS). Volgens de Indiase regering hebben de automatische stabilisatoren, zoals de ingevoerde werkloosheidsuitkeringen, onvoldoende dempende werking op de conjunctuur en moeten er nieuwe maatregelen worden genomen.$$, 'inline'),
  ('fa301532-9d01-4977-bf28-e8b3875efa9a', '1545093b-8501-42d0-bebe-0ec82fee64cd', $$Indiase burgers importeren goud tegen inflatie; importbeperkende maatregelen$$,
   $$economie-havo-2016-i-in-india-is-het-niet-alles-goud-wat-er-blinkt-context2.png$$,
   $$Om zich te beschermen tegen de oplopende inflatie importeren veel Indiase burgers goud en gouden sieraden uit de VS. De Indiase regering vindt dat onwenselijk en heeft importbeperkende maatregelen op goud en gouden sieraden aangekondigd. Over deze onderwerpen wordt in India druk getwitterd (zie bron 1).$$, 'inline'),
  ('d69f44fc-bb7d-45a4-a02d-a1e7c6309103', '1545093b-8501-42d0-bebe-0ec82fee64cd', $$Indiase econoom: renteverhoging in VS maakt goud uit de VS duurder$$,
   $$economie-havo-2016-i-in-india-is-het-niet-alles-goud-wat-er-blinkt-context3.png$$,
   $$Naar aanleiding van een krantenbericht (bron 2) doet een Indiase econoom een oproep aan de Indiase regering om af te zien van de importbeperkende maatregelen op goud en gouden sieraden. Hij stelt: “De renteverhoging in de VS zal gevolgen hebben voor de wisselkoers van de dollar in roepies, waardoor uiteindelijk Indiase burgers nog meer voor goud en gouden sieraden uit de VS moeten gaan betalen.”$$, 'inline'),
  ('09306483-39dc-4ee4-bd23-4cc75ab33aa7', '1545093b-8501-42d0-bebe-0ec82fee64cd', $$bron 1: twitter en de goudprijs (trending topics en tweets)$$,
   $$economie-havo-2016-i-in-india-is-het-niet-alles-goud-wat-er-blinkt-context4.png$$,
   $$bron 1 twitter en de goudprijs
In onderstaand figuur worden de meest voorkomende onderwerpen in tweets van Indiase burgers grafisch weergegeven (''trending topics''). Hoe groter de cirkel, des te vaker komt het onderwerp in tweets voor.
Een aantal tweets van Indiase burgers met daarin het woord ''goud'' zijn weergegeven.
figuur: cirkels met de onderwerpen India, inflatie, sparen, goud en roepie*
* geldeenheid in India
Aishwarya uit india schreef: Bijna trouwen! Wil mooie gouden sieraden dragen en moet bruidsschat meenemen. Maar goud uit de VS is sinds januari zo duur!
Balamani uit India schreef: Ik heb toch in de VS goud gekocht, want die roepie blijft maar zakken..!
Chudamani uit India schreef: Met die hoge inflatie kan ik beter mijn spaarrekening opheffen en mijn roepies in goud omzetten.$$, 'inline'),
  ('3a3e2aea-f8e9-42cf-9c82-38aef8f51a18', '1545093b-8501-42d0-bebe-0ec82fee64cd', $$bron 2: krantenbericht 'Fed verhoogt rente in VS'$$,
   $$economie-havo-2016-i-in-india-is-het-niet-alles-goud-wat-er-blinkt-context5.png$$,
   $$bron 2 uit een krant…
Fed verhoogt rente in VS
Na jaren van renteverlagingen heeft de centrale bank (Fed) van de Verenigde Staten aangekondigd de rente te verhogen. De Amerikaanse economie is herstellende van de kredietcrisis en volgens de voorzitter van de Fed is stimulering via een lage rente niet meer nodig. De voorzitter verwacht dat de renteverhoging zal leiden tot kapitaalimport vanuit landen zoals India.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('1e678187-67bb-4d75-b001-b36d1a9d2110', 'bf495dd6-34dc-49f1-a404-24237028d6b8', 1,
   '[{"domain": "Markt", "subdomain": "Marktvormen"}]'::jsonb,
   '["oligopolie", "monopolistische concurrentie", "aantal aanbieders", "marktkenmerken", "toetreding"]'::jsonb,
   $$Bepalen of na toetreding van een tweede aanbieder sprake is van monopolistische concurrentie of oligopolie.$$,
   $$economie-havo-2016-i-schipperen-naar-schierland-vraag1.png$$, $$1p 1 Is er na toetreding van Budgetboot op de markt van veerdiensten naar Schierland sprake van monopolistische concurrentie of oligopolie? Verklaar het antwoord.$$, array['a58fe309-a853-4c3b-b9b8-4ab0d744db6a']::uuid[]),
  ('768fda95-4141-48d6-8da6-86ae7a551e64', 'bf495dd6-34dc-49f1-a404-24237028d6b8', 2,
   '[{"domain": "Markt", "subdomain": "Producentengedrag"}]'::jsonb,
   '["maximale totale winst", "MO = MK", "marginale opbrengst", "prijs berekenen", "monopolie"]'::jsonb,
